const body = ($input.first().json.body) || $input.first().json || {};
const out = {};
out.max_calls = Math.min(parseInt(body.max_calls) || 5, 50);
out.target_hot = body.target_hot == null ? null : Number(body.target_hot);
out.branche = Array.isArray(body.branche) ? body.branche : (body.branche ? [body.branche] : []);
out.city = body.city || null;
out.cooldown_days = parseInt(body.cooldown_days) || 30;
out.dry_run = body.dry_run === undefined ? true : !!body.dry_run;
out.disclose_ratio = body.disclose_ratio == null ? 0.5 : Number(body.disclose_ratio);
out.session_id = 'sess_' + Date.now();
return [{ json: out }];

const p = $('Validate Params').first().json;
const ICP = ['Treuhand','Finanz','Immobilien','Rechtsbranche','Coaching / Beratung','Marketing / Agentur','Architektur','Unternehmensberatung'];
const leads = $input.all().map(i => i.json);
function prop(l, name){ const v = (l.properties||{})[name]; if(!v) return l[name]; if(v.rich_text) return (v.rich_text[0]||{}).plain_text||''; if(v.title) return (v.title[0]||{}).plain_text||''; if(v.phone_number!==undefined) return v.phone_number||''; if(v.select) return (v.select||{}).name||''; if(v.checkbox!==undefined) return v.checkbox; if(v.date) return (v.date||{}).start||null; if(v.number!==undefined) return v.number; return ''; }
function e164(raw){ let s=String(raw||'').replace(/[^0-9+]/g,''); if(!s) return null; if(s.startsWith('+')) return s; if(s.startsWith('00')) return '+'+s.slice(2); if(s.startsWith('0')) return '+41'+s.slice(1); if(s.startsWith('41')) return '+'+s; return null; }
const now = Date.now();
const out = [];
for (const l of leads){
  const phone = e164(prop(l,'phone'));
  if(!phone) continue;
  const branche = prop(l,'Branche');
  if(!ICP.includes(branche)) continue;
  if(p.branche.length && !p.branche.includes(branche)) continue;
  if(prop(l,'Stern Opt-Out') === true) continue;
  const attempts = Number(prop(l,'Call Attempts')||0);
  if(attempts >= 2) continue;
  const last = prop(l,'Last contacted');
  if(last){ const days=(now - new Date(last).getTime())/86400000; if(days < p.cooldown_days) continue; }
  const stage = prop(l,'Pipeline Stage');
  if(['Workflow Interview','Pilot','Paying Client','OUT'].includes(stage)) continue;
  out.push({ lead_id: l.id, firma: prop(l,'Firma')||prop(l,'Name'), branche, kontakt_nachname: prop(l,'Name')||'', phone, last_ts: last?new Date(last).getTime():0, attempts });
}
out.sort((a,b)=> a.last_ts - b.last_ts);
const picked = out.slice(0, p.max_calls);
const n = picked.length;
const threshold = Math.round(n * p.disclose_ratio);
return picked.map((x,idx)=>({ json: Object.assign({}, x, { dry_run: p.dry_run, session_id: p.session_id, disclosure_line: (idx < threshold) ? 'Kurz vorweg: Ich bin eine digitale Assistentin von automatisierbar. ' : '' }) }));

const items = $input.all().map(i=>i.json);
const res = { dialed: items.length, session_id: (items[0]||{}).session_id || null, leads: items.map(i=>({ firma:i.firma, phone:i.phone })) };
return [{ json: res }];

const items = $input.all().map(i=>i.json);
const res = { dry_run: true, eligible_count: items.length, eligible: items.map(i=>({ firma:i.firma, branche:i.branche, phone:i.phone })) };
return [{ json: res }];
